mapper.select:
SELECT g.id, g.name, g.number, g.spec, g.brand, g.unit, g.code, g.data, g.batch, g.protect, g.threshold,
c.id as "categoryData.id", c.pid as "categoryData.pid", c.name as "categoryData.name", c.sort as "categoryData.sort", c.data as "categoryData.data",
( SELECT COALESCE(SUM(r2.nums), 0) FROM room r2 WHERE r2.goods = g.id
AND r2.warehouse IN
#{warehouseId}
) as totalStock FROM goods g LEFT JOIN category c ON g.category = c.id WHERE g.batch = 1
AND g.id = #{query.goodsId}
AND g.number = #{query.goodsNumber}
AND g.spec = #{query.goodsSpec}
AND g.category = #{query.goodsCategoryId}
AND g.brand = #{query.goodsBrand}
AND g.code = #{query.goodsCode}
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND b.number LIKE CONCAT('%', #{query.batchNumber}, '%') )
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND DATE(b.time) = #{query.productDate} )
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND b.nums < g.threshold )
AND EXISTS ( SELECT 1 FROM room r3 WHERE r3.goods = g.id AND r3.warehouse IN
#{warehouseId}
)
GROUP BY g.id, c.id ORDER BY g.name

SELECT b.id as batchId, b.number as batchNumber, b.time as createTime, b.nums as nums, b.goods as goodsId, b.room as room FROM batch b WHERE b.goods IN
#{goodsId}
ORDER BY b.time DESC

SELECT r.id as storedRecordId, r.warehouse as warehouseId, w.name as warehouseName, b.goods as goodsId, b.id as batchId, r.nums as stockNum FROM batch b INNER JOIN room r ON b.goods = r.goods LEFT JOIN warehouse w ON r.warehouse = w.id WHERE b.goods IN
#{goodsId}
ORDER BY b.id, r.warehouse
